import styled from 'styled-components'
import { cores } from '../../styles'
import bgheader from '../../assets/images.nova/Vector.svg'

export const HeaderBar = styled.header`
  background-color: ${cores.cinza};
  padding: 40px;
  height: 385px;
  display: flex;
  text-align: center;
  background-image: url(${bgheader});
  flex-direction: column; // Para permitir que os elementos sejam empilhados verticalmente

  img {
    display: block; // Garante que o img será exibido como bloco
    width: 125px;
    margin: 0 auto; // Centraliza a imagem horizontalmente
  }

  div {
    display: flex;
    flex-direction: column; // Para que os filhos (img e h1) fiquem empilhados
    width: 100%;
    height: 300px;
    justify-content: flex-end; // Faz o conteúdo (h1) ir para o fundo da div

    h1 {
      font-size: 36px;
      font-weight: 900;
      width: 539px;
      line-height: 42.2px;
      margin: 0 auto;
    }
  }
`

export const Links = styled.ul`
  display: flex;
  margin-left: 40px;
`

export const LinkItem = styled.li`
  margin-right: 16px;
`

export const LinkCart = styled.a`
  display: flex;

  img {
    margin-left: 16px;
  }
`
